const point=(wx,wy)=>[mx+wx*scale,my+wy*scale];
islandPolys.forEach((poly,i)=>{const points=poly.map(([wx,wy])=>point(wx,wy));polygon(points,'#ddca92',1.5);polygon(points,i===4&&!state.ferryTicket?'#8e899e':'#95b47b');});
